public struct FfiConverterTypeAngleUnit: FfiConverterRustBuffer {
    typealias SwiftType = AngleUnit

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AngleUnit {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .deg
        
        case 2: return .rad
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AngleUnit, into buf: inout [UInt8]) {
        switch value {
        
        
        case .deg:
            writeInt(&buf, Int32(1))
        
        
        case .rad:
            writeInt(&buf, Int32(2))
        
        }
    }
}


